//! display/dc/dce/dce_aux.{h,c} (Linux 6.18.55), with the `aux_engine_regs`/
//! `aux_shift`/`aux_mask` table of dcn21_resource.c: the DP AUX engines of
//! Renoir's ddc loop. Renoir has `res_cap_rn.num_ddc` (5) of them, on DP_AUX0..4.
//!
//! `dcn21_aux_engine_create` → `dce110_aux_engine_construct` stores the instance,
//! funcs identity, register pointers and the polling timeout; it writes no
//! register. The register table is machine-generated by `dcgen.py` from
//! `AUX_COMMON_REG_LIST0` / `DCN_AUX_MASK_SH_LIST`, and the three non-SRI fields
//! the resource wrapper adds (AUXN_IMPCAL/AUXP_IMPCAL = 0, AUX_RESET_MASK) are
//! filled into the generated table below.
#![allow(dead_code)]

use crate::regs::*;
use alloc::boxed::Box;

/// AUX timeout (dce_aux.h enum): the SW poll budget is MULTIPLIER × PERIOD =
/// 6 × 400 = 2400 µs (normal AUX_SW_DONE arrives within ~240 µs).
const AUX_TIMEOUT_PERIOD: u32 = 400;
const SW_AUX_TIMEOUT_PERIOD_MULTIPLIER: u32 = 6;

/// Which `dce_aux_funcs` vtable the base points at (dce_aux.c). For a
/// Renoir-class engine (extended_aux_timeout_support), the vtable also gains
/// `configure_timeout`; that override is part of the hwss-stage vtable build.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum dce_aux_funcs {
    aux_functions,
}

/// `struct dce_aux` (dce_aux.h): the AUX engine base. `ddc` is None until the
/// ddc service lands; `ctx` is not stored (see `clock_source`). `delay` /
/// `max_defer_write_retry` are in milliseconds.
#[derive(Default)]
pub struct dce_aux {
    pub inst: u32,
    // ddc: Option<&ddc> — None until the ddc service lands.
    pub delay: u32,
    pub max_defer_write_retry: u32,
    pub acquire_reset: bool,
    pub funcs: Option<dce_aux_funcs>,
}

/// The `addr` cache of `aux_engine_dce110` (decoded register addresses). The
/// construct leaves it zeroed; it is filled on first use in the hwss stage.
#[derive(Default)]
pub struct aux_engine_dce110_addr {
    pub aux_control: u32,
    pub aux_arb_control: u32,
    pub aux_sw_data: u32,
    pub aux_sw_control: u32,
    pub aux_interrupt_control: u32,
    pub aux_dphy_rx_control1: u32,
    pub aux_dphy_rx_control0: u32,
    pub aux_sw_status: u32,
}

/// `struct aux_engine_dce110` (dce_aux.h): the concrete AUX engine.
#[derive(Default)]
pub struct aux_engine_dce110 {
    pub base: dce_aux,
    pub regs: Option<&'static dce110_aux_registers>,
    pub mask: Option<&'static dce110_aux_registers_mask>,
    pub shift: Option<&'static dce110_aux_registers_shift>,
    pub addr: aux_engine_dce110_addr,
    pub polling_timeout_period: u32,
}

/// `dce110_aux_engine_construct` (dce_aux.c): store the instance, funcs and
/// registers. `is_ext_aux_timeout_configurable` (true on Renoir) adds
/// `configure_timeout` to the funcs vtable — modelled with the funcs identity
/// here; the concrete vtable is built in the hwss stage.
pub fn dce110_aux_engine_construct(
    aux_engine110: &mut aux_engine_dce110,
    inst: u32,
    timeout_period: u32,
    regs: &'static dce110_aux_registers,
    mask: &'static dce110_aux_registers_mask,
    shift: &'static dce110_aux_registers_shift,
    is_ext_aux_timeout_configurable: bool,
) {
    aux_engine110.base.delay = 0;
    aux_engine110.base.max_defer_write_retry = 0;
    aux_engine110.base.inst = inst;
    aux_engine110.polling_timeout_period = timeout_period;
    aux_engine110.regs = Some(regs);
    aux_engine110.mask = Some(mask);
    aux_engine110.shift = Some(shift);
    aux_engine110.base.funcs = Some(dce_aux_funcs::aux_functions);
    let _ = is_ext_aux_timeout_configurable; // vtable configure_timeout: hwss stage
}

/// `dcn21_aux_engine_create` (dcn21_resource.c): allocate and construct the AUX
/// engine for ddc index `inst`. `extended_aux_timeout_support` comes from
/// `dc.caps` (true on Renoir).
pub fn dcn21_aux_engine_create(inst: u32, extended_aux_timeout_support: bool) -> Box<aux_engine_dce110> {
    let mut aux_engine = Box::new(aux_engine_dce110::default());
    dce110_aux_engine_construct(
        &mut aux_engine,
        inst,
        SW_AUX_TIMEOUT_PERIOD_MULTIPLIER * AUX_TIMEOUT_PERIOD,
        &AUX_REGS[inst as usize],
        &AUX_MASK,
        &AUX_SHIFT,
        extended_aux_timeout_support,
    );
    aux_engine
}

// ── machine-generated by dcgen.py (AUX_COMMON_REG_LIST0 / DCN_AUX_MASK_SH_LIST),
//    with the three non-SRI wrapper fields (AUXN_IMPCAL/AUXP_IMPCAL/AUX_RESET_MASK) added ──
